using System;using System.Collections.Generic;
namespace UnityEngine{
 public struct Vector2 {public float x,y;public Vector2(float x,float y){this.x=x;this.y=y;}public static Vector2 up=>new Vector2(0,1);public static Vector2 right=>new Vector2(1,0);public static Vector2 operator+(Vector2 a,Vector2 b)=>new Vector2(a.x+b.x,a.y+b.y);public static Vector2 operator*(Vector2 a,float s)=>new Vector2(a.x*s,a.y*s);}
 public struct Color{public float r,g,b,a;public Color(float r,float g,float b){this.r=r;this.g=g;this.b=b;a=1;}}
 public static class Mathf{public const float PI=(float)Math.PI;public static float Clamp(float x,float a,float b)=>Math.Max(a,Math.Min(b,x));public static float Min(float a,float b)=>Math.Min(a,b);public static float Cos(float x)=>(float)Math.Cos(x);public static float Sin(float x)=>(float)Math.Sin(x);}
}
namespace ReversalTower{
 using UnityEngine;public enum ScreenMode{Battle,Result}public enum AttackKind{Slash,Volley,Rain}public class Pattern{public string id;public AttackKind kind;}
 public class BP{public bool struck;}public class TowerGame{public ScreenMode mode;public int bossIndex,attackStep,bossFace=1;public float seconds,patternAge,windup=1;public Pattern current;public Vector2 boss;public BP BossPatterns=new BP();public List<Hazard> hazards=new List<Hazard>();public class Hazard{public float delay,x,width;public string pattern;}}
 public static class Palette{public static Color Gold=new Color(1,.7f,.3f),White=new Color(1,1,1),Purple=new Color(.6f,.4f,1);public static Color Alpha(Color c,float a){c.a=a;return c;}}
 public sealed partial class WorldArtist{TowerGame g=new TowerGame();int lines;void Line(Vector2 a,Vector2 b,float w,Color c){if(w<0||c.a>.51)throw new Exception("invalid accent");lines++;}public static void Main(){int tests=0;for(int boss=0;boss<5;boss++){var w=new WorldArtist();w.g.bossIndex=boss;w.g.current=new Pattern{id="test",kind=AttackKind.Slash};w.BossPatternAccents();w.g.seconds=.1f;w.g.patternAge=.9f;w.g.attackStep=1;w.BossPatternAccents();if(w.accents.Count!=0)throw new Exception("early impact");w.g.seconds=.2f;w.g.patternAge=1;w.g.attackStep=2;w.BossPatternAccents();if(w.accents.Count!=1||w.lines==0)throw new Exception("missing strike");w.BossPatternAccents();if(w.accents.Count!=1)throw new Exception("duplicate render");w.g.hazards.Add(new TowerGame.Hazard{delay=.5f,width=3,pattern="rain"});w.BossPatternAccents();if(w.accents.Count!=1)throw new Exception("early hazard");w.g.hazards[0].delay=0;w.BossPatternAccents();if(w.accents.Count!=2)throw new Exception("missing hazard");w.g.seconds=1;w.BossPatternAccents();if(w.accents.Count!=0)throw new Exception("stale effect");w.g.mode=ScreenMode.Result;w.BossPatternAccents();if(w.activeHazards.Count!=0)throw new Exception("state leak");tests+=7;}Console.WriteLine("BOSS_ACCENT_TESTS_PASSED "+tests);}}
}
